{"kind":"test-title-selector","source_revision":"1fda3eb161b042aae66e4adcc07319f69946dadd","path":"packages/cli/test/shisa-connect-integration.test.mjs","start":12825,"end":12899,"raw_source":""cancelling before approval leaves the session signed out and unrefreshed"","token_kind":"string","test_owner":{"title_source":""cancelling before approval leaves the session signed out and unrefreshed"","registration_line":364,"start":12820,"end":13662,"registration_guards":[]},"guards":[],"call_name":"test","argument_index":0,"call_source":"test("cancelling before approval leaves the session signed out and unrefreshed", async (t) => {
	const h = await harness(t, { token: "pending" });
	focusAccount(h.component);
	h.component.handleInput("enter");
	await waitFor(() => h.requests.some((request) => request.url === "/device/token"));
	assert.match(h.component.render(100).join("\n"), /JOUZU-LOOP-0001/u, "the device code is visible while polling");
	h.component.handleInput("escape");
	await waitFor(() => h.component.busy === false);

	assert.equal(readShisaLoginToken(h.paths), undefined, "cancelling never saves a credential");
	assert.equal(
		h.requests.some((request) => request.url === "/v1/jouzu/model-catalog"),
		false,
	);
	assert.equal(h.runtime.getModels().some(isCatalogModel), false);
	assert.match(h.component.render(100).join("\n"), /Shisa sign-in cancelled/u);
})","selector_identity":{"potential_registration_count":1,"bindings":null,"derived_report_names":["cancelling before approval leaves the session signed out and unrefreshed"]}}

