{"kind":"test-title-selector","source_revision":"1fda3eb161b042aae66e4adcc07319f69946dadd","path":"packages/cli/test/shisa-connect-integration.test.mjs","start":13670,"end":13750,"raw_source":""an unconfirmed acknowledgement warns but keeps the signed-in catalog available"","token_kind":"string","test_owner":{"title_source":""an unconfirmed acknowledgement warns but keeps the signed-in catalog available"","registration_line":382,"start":13665,"end":14610,"registration_guards":[]},"guards":[],"call_name":"test","argument_index":0,"call_source":"test("an unconfirmed acknowledgement warns but keeps the signed-in catalog available", async (t) => {
	const h = await harness(t, { ackStatus: 503 });
	focusAccount(h.component);
	h.component.handleInput("enter");
	await waitFor(() => h.component.busy === false);

	const text = h.component.render(100).join("\n");
	assert.match(text, /confirmation failed/u, "the acknowledgement warning survives the resolution");
	assert.match(text, /Sign in again/u);
	assert.doesNotMatch(text, /Connected to Shisa AI\./u, "an unacknowledged sign-in never reports plain success");
	assert.equal(
		readShisaLoginToken(h.paths),
		"shsk:loopback-secret",
		"the credential is saved regardless of acknowledgement",
	);
	assert.ok(
		h.requests.some((request) => request.url === "/device/link/ack"),
		"the acknowledgement was attempted",
	);
	assert.ok((await h.runtime.getAvailable()).some(isCatalogModel), "the saved credential still unlocks the catalog");
})","selector_identity":{"potential_registration_count":1,"bindings":null,"derived_report_names":["an unconfirmed acknowledgement warns but keeps the signed-in catalog available"]}}

