{"kind":"test-title-selector","source_revision":"1fda3eb161b042aae66e4adcc07319f69946dadd","path":"packages/cli/test/shisa-connect-integration.test.mjs","start":20722,"end":20809,"raw_source":""interactive cancellation after authorization reports signed in with refresh cancelled"","token_kind":"string","test_owner":{"title_source":""interactive cancellation after authorization reports signed in with refresh cancelled"","registration_line":554,"start":20717,"end":21786,"registration_guards":[]},"guards":[],"call_name":"test","argument_index":0,"call_source":"test("interactive cancellation after authorization reports signed in with refresh cancelled", async (t) => {
	const entered = Promise.withResolvers();
	const settled = Promise.withResolvers();
	const h = await harness(t, {
		pickerOptions: firstUseOptions,
		onRefreshSettled: () => settled.resolve(),
		catalogFetch: async (_url, { signal }) => {
			entered.resolve();
			return new Promise((_resolve, reject) =>
				signal.addEventListener("abort", () => reject(signal.reason), { once: true }),
			);
		},
	});
	const ui = interactiveLoginHost(h.session);
	await withPiAuthCompletion(async () => {
		const login = ui.login();
		await entered.promise;
		ui.focused.handleInput("\u001b");
		await login;
		await settled.promise;
	});
	assert.ok(readShisaLoginToken(h.paths));
	assert.equal(h.session.model?.id, "unknown");
	assert.deepEqual(ui.errors, []);
	assert.deepEqual(ui.statuses, ["Signed in to Shisa; catalog refresh cancelled. Run /reload to load Shisa models."]);
	assert.equal(ui.refreshes.length, 0, "completion must not restart the cancelled refresh");
})","selector_identity":{"potential_registration_count":1,"bindings":null,"derived_report_names":["interactive cancellation after authorization reports signed in with refresh cancelled"]}}

