{"kind":"test-title-selector","source_revision":"1fda3eb161b042aae66e4adcc07319f69946dadd","path":"packages/cli/test/shisa-connect-integration.test.mjs","start":24756,"end":24820,"raw_source":""a delayed catalog default applies only until a model is chosen"","token_kind":"string","test_owner":{"title_source":""a delayed catalog default applies only until a model is chosen"","registration_line":658,"start":24751,"end":25605,"registration_guards":[]},"guards":[],"call_name":"test","argument_index":0,"call_source":"test("a delayed catalog default applies only until a model is chosen", async (t) => {
	const behavior = { catalogDocument: priorityCatalog({ priorities: false }), pickerOptions: firstUseOptions };
