{"kind":"test-title-selector","source_revision":"1fda3eb161b042aae66e4adcc07319f69946dadd","path":"packages/cli/test/shisa-connect-integration.test.mjs","start":27612,"end":27693,"raw_source":""automatic selection crosses an asynchronous host hook without waiting on itself"","token_kind":"string","test_owner":{"title_source":""automatic selection crosses an asynchronous host hook without waiting on itself"","registration_line":726,"start":27607,"end":28303,"registration_guards":[]},"guards":[],"call_name":"test","argument_index":0,"call_source":"test("automatic selection crosses an asynchronous host hook without waiting on itself", async (t) => {
	let restore;
	const h = await harness(t, {
		catalogDocument: priorityCatalog(),
		pickerOptions: firstUseOptions,
		selectionDelegate: {
			version: 1,
			attach(session) {
				const original = session.setModel;
				session.setModel = async (...args) => {
					await Promise.resolve();
					return original.apply(session, args);
				};
				restore = () => {
					session.setModel = original;
				};
			},
			dispose() {
				restore?.();
			},
			async submit(_submission, dispatch) {
				await dispatch();
			},
		},
	});
	await login(h);
	assert.equal(h.session.model?.id, "flash-next");
})","selector_identity":{"potential_registration_count":1,"bindings":null,"derived_report_names":["automatic selection crosses an asynchronous host hook without waiting on itself"]}}

