{"kind":"test-title-selector","source_revision":"1fda3eb161b042aae66e4adcc07319f69946dadd","path":"packages/cli/test/shisa-connect-integration.test.mjs","start":30540,"end":30612,"raw_source":""cancelling login during default authentication prevents model mutation"","token_kind":"string","test_owner":{"title_source":""cancelling login during default authentication prevents model mutation"","registration_line":817,"start":30535,"end":31471,"registration_guards":[]},"guards":[],"call_name":"test","argument_index":0,"call_source":"test("cancelling login during default authentication prevents model mutation", async (t) => {
	const settled = Promise.withResolvers();
	let auth;
	const h = await harness(t, {
		catalogDocument: priorityCatalog(),
		pickerOptions: firstUseOptions,
		onRefreshSettled: () => settled.resolve(),
		prepareRuntime(runtime) {
			auth = holdNextCatalogAuth({ runtime }, true);
		},
	});
	t.after(auth.release);
	const controller = new AbortController();
	const signingIn = login(h, controller.signal);
	const rejected = assert.rejects(signingIn, /Login cancelled/);
	await auth.entered;
