{"kind":"test-title-selector","source_revision":"1fda3eb161b042aae66e4adcc07319f69946dadd","path":"packages/cli/test/shisa-connect-integration.test.mjs","start":34906,"end":34994,"raw_source":""custom turns drain in-flight selection before dispatch and close first-use eligibility"","token_kind":"string","test_owner":{"title_source":""custom turns drain in-flight selection before dispatch and close first-use eligibility"","registration_line":942,"start":34901,"end":36206,"registration_guards":[]},"guards":[],"call_name":"test","argument_index":0,"call_source":"test("custom turns drain in-flight selection before dispatch and close first-use eligibility", async (t) => {
	const behavior = { catalogDocument: priorityCatalog(), pickerOptions: firstUseOptions };
	const h = await harness(t, behavior);
	const dispatched = [];
	h.session.agent.streamFunction = async (model) => {
		dispatched.push(model.id);
		const final = { ...assistant(), provider: model.provider, model: model.id, api: model.api };
		return {
			async *[Symbol.asyncIterator]() {
				yield { type: "done", partial: final };
			},
			result: async () => final,
		};
	};
	const auth = holdNextCatalogAuth(h);
	t.after(auth.release);
	const signingIn = login(h);
	await auth.entered;
	const turn = h.session.sendCustomMessage(
		{ customType: "fixture", content: "hello", display: false },
		{ triggerTurn: true },
	);
	await new Promise((resolve) => setImmediate(resolve));
	assert.deepEqual(dispatched, []);
	auth.release();
	await Promise.all([signingIn, turn]);
	assert.deepEqual(dispatched, ["flash-next"]);
	behavior.catalogDocument = priorityCatalog({ sequence: "2" });
	behavior.catalogDocument.modelOfferings.find((offering) => offering.modelId === "flash").metadata.default = 200;
	await h.picker.refreshShisaAccount({ signedIn: true });
	assert.equal(h.session.model?.id, "flash-next");
})","selector_identity":{"potential_registration_count":1,"bindings":null,"derived_report_names":["custom turns drain in-flight selection before dispatch and close first-use eligibility"]}}

