{"kind":"test-title-selector","source_revision":"1fda3eb161b042aae66e4adcc07319f69946dadd","path":"packages/cli/test/updater.test.mjs","start":7253,"end":7325,"raw_source":""install-channel lookup is cached after global and local classification"","token_kind":"string","test_owner":{"title_source":""install-channel lookup is cached after global and local classification"","registration_line":199,"start":7248,"end":8342,"registration_guards":[]},"guards":[],"call_name":"test","argument_index":0,"call_source":"test("install-channel lookup is cached after global and local classification", () => {
