{"kind":"test-title-selector","source_revision":"1fda3eb161b042aae66e4adcc07319f69946dadd","path":"packages/cli/test/updater.test.mjs","start":10094,"end":10154,"raw_source":""registry check records a newer integrity-qualified release"","token_kind":"string","test_owner":{"title_source":""registry check records a newer integrity-qualified release"","registration_line":276,"start":10089,"end":11040,"registration_guards":[]},"guards":[],"call_name":"test","argument_index":0,"call_source":"test("registry check records a newer integrity-qualified release", () => {
	const context = fixture();
	const latest = release("0.1.1");
	const npm = fakeNpm({ currentVersion: "0.1.0", latest, globalRoot: context.globalRoot });
	try {
		const updater = new JouzuUpdater({
			paths: context.paths,
			currentVersion: "0.1.0",
			executable: context.executable,
			packageRoot: context.packageRoot,
			runNpm: npm.run,
			now: () => new Date("2026-08-20T12:00:00.000Z"),
		});
		assert.deepEqual(updater.check(), {
			status: "available",
			installedVersion: "0.1.0",
			version: "0.1.1",
