{"kind":"test-title-selector","source_revision":"1fda3eb161b042aae66e4adcc07319f69946dadd","path":"packages/cli/test/updater.test.mjs","start":11048,"end":11133,"raw_source":""offline registry failures preserve the current install and schedule a bounded retry"","token_kind":"string","test_owner":{"title_source":""offline registry failures preserve the current install and schedule a bounded retry"","registration_line":304,"start":11043,"end":12068,"registration_guards":[]},"guards":[],"call_name":"test","argument_index":0,"call_source":"test("offline registry failures preserve the current install and schedule a bounded retry", () => {
	const context = fixture();
	try {
		const updater = new JouzuUpdater({
			paths: context.paths,
			currentVersion: "0.1.0",
			executable: context.executable,
			packageRoot: context.packageRoot,
			runNpm: (args) =>
				args[0] === "view"
					? { status: 1, stdout: "", stderr: "offline" }
					: { status: 0, stdout: `${context.globalRoot}\n`, stderr: "" },
			now: () => new Date("2026-08-20T12:00:00.000Z"),
		});
		assert.throws(
			() => updater.check(),
			(error) => error instanceof UpdateError && error.code === "npm-view-exit",
		);
		const state = JSON.parse(readFileSync(updateStatePath(context.paths), "utf8"));
