{"kind":"test-title-selector","source_revision":"1fda3eb161b042aae66e4adcc07319f69946dadd","path":"packages/cli/test/updater.test.mjs","start":12076,"end":12152,"raw_source":""global update downloads, verifies, installs, records, and requests restart"","token_kind":"string","test_owner":{"title_source":""global update downloads, verifies, installs, records, and requests restart"","registration_line":332,"start":12071,"end":13172,"registration_guards":[]},"guards":[],"call_name":"test","argument_index":0,"call_source":"test("global update downloads, verifies, installs, records, and requests restart", () => {
	const context = fixture();
	const latest = release("0.1.1");
	const npm = fakeNpm({ currentVersion: "0.1.0", latest, globalRoot: context.globalRoot });
	try {
		const updater = new JouzuUpdater({
			paths: context.paths,
			currentVersion: "0.1.0",
			executable: context.executable,
			packageRoot: context.packageRoot,
			runNpm: npm.run,
			verifyInstalled: (expected) => assert.equal(npm.installedVersion(), expected),
			now: () => new Date("2026-08-20T12:00:00.000Z"),
		});
		assert.deepEqual(updater.startup(), { action: "restart", version: "0.1.1" });
		assert.equal(npm.installedVersion(), "0.1.1");
		const state = JSON.parse(readFileSync(updateStatePath(context.paths), "utf8"));
		assert.equal(state.lastResult, "updated");
		assert.equal(state.installedVersion, "0.1.1");
		assert.equal(state.previousVersion, "0.1.0");
		assert.ok(npm.calls.some((args) => args[0] === "install" && args.includes("--ignore-scripts")));
	} finally {
		rmSync(context.root, { recursive: true, force: true });
	}
})","selector_identity":{"potential_registration_count":1,"bindings":null,"derived_report_names":["global update downloads, verifies, installs, records, and requests restart"]}}

