{"kind":"test-title-selector","source_revision":"1fda3eb161b042aae66e4adcc07319f69946dadd","path":"packages/cli/test/updater.test.mjs","start":13180,"end":13263,"raw_source":""a failed install leaves a still-verified current version running without rollback"","token_kind":"string","test_owner":{"title_source":""a failed install leaves a still-verified current version running without rollback"","registration_line":358,"start":13175,"end":14145,"registration_guards":[]},"guards":[],"call_name":"test","argument_index":0,"call_source":"test("a failed install leaves a still-verified current version running without rollback", () => {
	const context = fixture();
	const latest = release("0.1.1");
	const npm = fakeNpm({
		currentVersion: "0.1.0",
		latest,
		globalRoot: context.globalRoot,
		failCandidateInstall: true,
	});
	try {
		const updater = new JouzuUpdater({
			paths: context.paths,
			currentVersion: "0.1.0",
			executable: context.executable,
			packageRoot: context.packageRoot,
			runNpm: npm.run,
			verifyInstalled: (expected) => assert.equal(npm.installedVersion(), expected),
		});
		const result = updater.startup();
		assert.equal(result.action, "continue");
		assert.ok(result.message);
		assert.match(catalogMessageText(defaultCatalog(), result.message), /update-not-installed/);
		assert.equal(npm.installedVersion(), "0.1.0");
		assert.equal(npm.calls.filter((args) => args[0] === "install").length, 1);
	} finally {
		rmSync(context.root, { recursive: true, force: true });
	}
})","selector_identity":{"potential_registration_count":1,"bindings":null,"derived_report_names":["a failed install leaves a still-verified current version running without rollback"]}}

