{"kind":"test-title-selector","source_revision":"1fda3eb161b042aae66e4adcc07319f69946dadd","path":"packages/cli/test/updater.test.mjs","start":15377,"end":15452,"raw_source":""a cached available release survives the check-to-install process boundary"","token_kind":"string","test_owner":{"title_source":""a cached available release survives the check-to-install process boundary"","registration_line":426,"start":15372,"end":16339,"registration_guards":[]},"guards":[],"call_name":"test","argument_index":0,"call_source":"test("a cached available release survives the check-to-install process boundary", () => {
	const context = fixture();
	const latest = release("0.1.1");
	const npm = fakeNpm({ currentVersion: "0.1.0", latest, globalRoot: context.globalRoot });
	try {
		const updater = new JouzuUpdater({
			paths: context.paths,
			currentVersion: "0.1.0",
			executable: context.executable,
			packageRoot: context.packageRoot,
			runNpm: npm.run,
			verifyInstalled: (expected) => assert.equal(npm.installedVersion(), expected),
			now: () => new Date("2026-08-20T12:00:00.000Z"),
		});
		assert.equal(updater.check().status, "available");
		npm.calls.length = 0;
		assert.deepEqual(updater.startup(), { action: "restart", version: "0.1.1" });
		assert.equal(
			npm.calls.some((args) => args[0] === "view"),
			false,
		);
		assert.equal(
			npm.calls.some((args) => args[0] === "install"),
			true,
		);
	} finally {
		rmSync(context.root, { recursive: true, force: true });
	}
})","selector_identity":{"potential_registration_count":1,"bindings":null,"derived_report_names":["a cached available release survives the check-to-install process boundary"]}}

