{"kind":"test-title-selector","source_revision":"1fda3eb161b042aae66e4adcc07319f69946dadd","path":"packages/cli/test/updater.test.mjs","start":17057,"end":17136,"raw_source":""an active update lock blocks a concurrent installer without deleting the lock"","token_kind":"string","test_owner":{"title_source":""an active update lock blocks a concurrent installer without deleting the lock"","registration_line":477,"start":17052,"end":18237,"registration_guards":[]},"guards":[],"call_name":"test","argument_index":0,"call_source":"test("an active update lock blocks a concurrent installer without deleting the lock", () => {
	const context = fixture();
	const latest = release("0.1.1");
	const npm = fakeNpm({ currentVersion: "0.1.0", latest, globalRoot: context.globalRoot });
	try {
		mkdirSync(context.paths.stateDir, { recursive: true });
		const lockPath = join(context.paths.stateDir, "self-update.lock");
		const lock = `${JSON.stringify({ pid: process.pid, startedAt: new Date().toISOString(), token: "other" })}\n`;
		writeFileSync(lockPath, lock);
		const updater = new JouzuUpdater({
			paths: context.paths,
			currentVersion: "0.1.0",
			executable: context.executable,
			packageRoot: context.packageRoot,
			runNpm: npm.run,
		});
		assert.throws(
			() =>
				updater.apply({
					status: "available",
					installedVersion: "0.1.0",
					version: latest.version,
					integrity: latest.integrity,
				}),
			(error) => error instanceof UpdateError && error.code === "update-busy",
		);
		assert.equal(readFileSync(lockPath, "utf8"), lock);
		assert.equal(
			npm.calls.some((args) => args[0] === "install"),
			false,
		);
	} finally {
		rmSync(context.root, { recursive: true, force: true });
	}
