{"kind":"test-title-selector","source_revision":"1fda3eb161b042aae66e4adcc07319f69946dadd","path":"packages/cli/test/updater.test.mjs","start":19006,"end":19060,"raw_source":""notify and off policies never install during startup"","token_kind":"string","test_owner":{"title_source":""notify and off policies never install during startup"","registration_line":532,"start":19001,"end":19906,"registration_guards":[]},"guards":[],"call_name":"test","argument_index":0,"call_source":"test("notify and off policies never install during startup", () => {
	for (const policy of ["notify", "off"]) {
		const context = fixture();
		const latest = release("0.1.1");
		const npm = fakeNpm({ currentVersion: "0.1.0", latest, globalRoot: context.globalRoot });
		try {
			const updater = new JouzuUpdater({
				paths: context.paths,
				currentVersion: "0.1.0",
				executable: context.executable,
				packageRoot: context.packageRoot,
				runNpm: npm.run,
			});
			updater.setPolicy(policy);
			const result = updater.startup();
			assert.equal(result.action, "continue");
			if (policy === "notify") {
				assert.ok(result.message);
				assert.match(catalogMessageText(defaultCatalog(), result.message), /is available/);
			}
			assert.equal(
				npm.calls.some((args) => args[0] === "install"),
				false,
			);
		} finally {
			rmSync(context.root, { recursive: true, force: true });
		}
	}
})","selector_identity":{"potential_registration_count":1,"bindings":null,"derived_report_names":["notify and off policies never install during startup"]}}

